(()=>{'use strict';let data=null,loading=null;const URL='ffws-br-2026-s2/home-results.json?v=20260803-s2-dia2-v1';const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));async function load(){if(data)return data;if(loading)return loading;loading=fetch(URL,{cache:'default'}).then(r=>r.ok?r.json():Promise.reject(new Error('HTTP '+r.status))).then(v=>data=v).catch(()=>data={teams:[],players:[],status:'upcoming'}).finally(()=>loading=null);return loading}function title(id,text){const body=document.getElementById(id),h=body?.closest('.home-widget')?.querySelector('h3');if(h)h.textContent=text}function placeholder(text){return`<tr><td colspan="3" style="padding:24px 14px;text-align:center;color:var(--text-muted);font-weight:800">${esc(text)}</td></tr>`}function renderRows(payload){const teams=document.getElementById('home-tbody-teams'),players=document.getElementById('home-tbody-players');title('home-tbody-teams','🏆 Top 6 Times da WB 2026 S2');title('home-tbody-players','🎯 Top 6 Jogadores da WB 2026 S2');const teamBtn=teams?.closest('.home-widget')?.querySelector('button');if(teamBtn){teamBtn.textContent='VER CLASSIFICAÇÃO →';teamBtn.setAttribute('onclick',"navigate('ffws-br-s2-classificatoria')")}const playerBtn=players?.closest('.home-widget')?.querySelector('button');if(playerBtn){playerBtn.textContent='VER RANKING MVP →';playerBtn.setAttribute('onclick',"navigate('ffws-br-s2-mvp')")}if(teams)teams.innerHTML=(payload.teams||[]).length?(payload.teams||[]).slice(0,6).map((r,i)=>`<tr><td style="color:var(--accent);font-weight:900">${i+1}º</td><td style="text-align:left"><a href="equipe.html?time=${encodeURIComponent(r.team)}" style="color:#fff;text-decoration:none;font-weight:900">${esc(r.short||r.team)}</a><div style="font-size:.75em;color:#888">${Number(r.booyahs||0)} B! • ${Number(r.kills||0)} K</div></td><td style="color:var(--accent);font-weight:900">${Number(r.points||0)}</td></tr>`).join(''):placeholder('A temporada começa em 1º de agosto.');if(players)players.innerHTML=(payload.players||[]).length?(payload.players||[]).slice(0,6).map((r,i)=>`<tr><td style="color:var(--accent);font-weight:900">${i+1}º</td><td style="text-align:left"><a href="jogador.html?jogador=${encodeURIComponent(r.player)}&time=${encodeURIComponent(r.team||'')}" style="color:#fff;text-decoration:none;font-weight:900">${esc(r.player)}</a><div style="font-size:.75em;color:#888">${esc(r.team||'')} • ${Number(r.matches||0)} Q</div></td><td style="color:var(--accent);font-weight:900">${Number(r.kills||0)}</td></tr>`).join(''):placeholder('Ranking disponível após as primeiras quedas.')}window.cffHomeRenderFinalStats=function(){renderRows(data||{teams:[],players:[]});load().then(renderRows);return true};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>load().then(renderRows),{once:true});else load().then(renderRows)})();
